const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
test('Domestic economy verifies actual layouts and finite supplies, rejecting steep route interiors',async()=>{const {DOMESTIC_SCENES,domesticRecipe,completeDomesticPaths}=await import('../domestic-scenes.js'),{planAssembly}=await import('../tile-adapter.js'),{emptyBoard,editBoard,cellWorld}=await import('../playground-model.js'),{boardTiles,boardHeight,BOARD_CELLS,validateFootprints}=await import('../board-terrain.js'),{resolveBoardEconomy,evolveBoardEconomy}=await import('../board-economy.js');const types=['home','garden','woodland','pottery','preservation','gathering','animals'],presets=['courtyard','kitchen','coppice','kiln','roots','meal','care'],cells=[{q:0,r:0},{q:1,r:0},{q:0,r:1},{q:-1,r:1},{q:-1,r:0},{q:0,r:-1},{q:1,r:-1}];let b=emptyBoard('economy');const requirements={};for(let i=0;i<types.length;i++){const type=types[i],recipe=domesticRecipe(type,presets[i],41+i*11);requirements[type]=recipe.requirements;b=editBoard(b,'place',{card:{id:type,revision:1,cells:[{q:0,r:0}],rendition:{meshes:[]},recipe,capabilities:DOMESTIC_SCENES[type].capabilities},newInstanceId:type,...cells[i]});}let a=completeDomesticPaths(planAssembly({tiles:boardTiles(b)},{requirementsByType:requirements}));assert.deepEqual(a.warnings,[]);const index=JSON.parse(fs.readFileSync(path.join(__dirname,'../domestic-assets/index.json'),'utf8')),catalog=JSON.parse(fs.readFileSync(path.join(__dirname,'../simulation-assets/catalog.json'),'utf8')),tree=catalog.find(x=>x.id==='tree-standing'),parts=JSON.parse(fs.readFileSync(path.join(__dirname,'..',tree.json),'utf8')),xs=[],zs=[];for(const part of parts)for(let i=0;i<part.positions.length;i+=3){xs.push(part.positions[i]);zs.push(part.positions[i+2]);}const dims={'tree-standing':{w:(Math.max(...xs)-Math.min(...xs))*2,d:(Math.max(...zs)-Math.min(...zs))*2}};const {planComposition}=await import('../board-composition.js');const flat=resolveBoardEconomy(b,a,()=>0,index,dims);assert.equal(flat.report.connectedInstanceIds.length,7);b={...b,instances:b.instances.map(i=>({...i,q:i.q-4,r:i.r+3}))};validateFootprints(b);a=planComposition(b).assembly;const terrain=boardHeight(a);assert.equal(terrain.grading.valid,true);let resolved=resolveBoardEconomy(b,a,terrain,index,dims);assert.equal(resolved.report.connectedInstanceIds.length,7,JSON.stringify(resolved.accessWarnings));assert.throws(()=>evolveBoardEconomy({...b,revision:b.revision+1},resolved,'day'),/stale/);assert.throws(()=>evolveBoardEconomy(b,resolved,'day',{days:0}),/at least/);b=evolveBoardEconomy(b,resolved,'supplies');resolved=resolveBoardEconomy(b,a,terrain,index,dims);b=evolveBoardEconomy(b,resolved,'day',{days:6});resolved=resolveBoardEconomy(b,a,terrain,index,dims);assert(resolved.report.goals.every(g=>g.ready));assert.equal(resolved.report.stock.clay,18);const steep=resolveBoardEconomy(b,a,(x,z)=>x,index,dims);assert(steep.report.connectedInstanceIds.length<7);assert(steep.accessWarnings.length);});
